def ori_records(a, marker=None):
    rec=[]
    for refl in [False,True]:
        b=np.fliplr(a) if refl else a
        mk=None
        if marker is not None:
            mm=np.zeros_like(a); mm[marker]=1
            mm=np.fliplr(mm) if refl else mm
        for k in range(4):
            x=np.rot90(b,-k)
            mm2=np.rot90(mm,-k) if marker is not None else None
            if not any(np.array_equal(x,r[1]) for r in rec):
                coord=tuple(np.argwhere(mm2)[0]) if marker is not None else None
                rec.append((f"{'F' if refl else ''}R{k*90}",x,coord))
    return rec
