def solve_anchor(anchorname, anchormask):
    sols=[]; visited=set(); nodect=0
    def dfs(occ, used, chosen):
        nonlocal nodect
        nodect+=1
        if len(used)==4:
            if occ==FULL: sols.append(tuple(chosen))
            return len(sols)>=maxsolutions
        rem=FULL ^ occ
        # choose uncovered cell with least valid placements
        best=None; bestopts=None; bits=rem
        while bits:
            bit=bits & -bits; idx=bit.bit_length()-1; bits-=bit
            opts=[]
            for color in [2,3,8]:
                if color in used: continue
                for p in bycell[color][idx]:
                    bm=p[4]
                    if bm & occ == 0:
                        opts.append(p)
            if not opts: return False
            if bestopts is None or len(opts)<len(bestopts):
                best=idx; bestopts=opts
                if len(bestopts)==1: break
        # rank placements perhaps maximize near full and reduce next constraints
        for p in bestopts:
            color,name,r,c,bm=p
            if dfs(occ|bm, used|{color}, chosen+[p]): return True
        return False
    dfs(anchormask,{7},[(7,anchorname,0,0,anchormask)])
    return sols,nodect
