# generic exact tiling solver for training checks

def solve_tiling(piece_arrays, boardN, marker_color=7, marker=None, maxsol=1000, sortmethod='MRV'):
    full=(1<<(boardN*boardN))-1
    def mkbits(a,r,c):
        bm=0
        for rr,cc in np.argwhere(a): bm |= 1<<((r+int(rr))*boardN+c+int(cc))
        return bm
    # anchors
    ar=[]
    for name,a,pt in ori_records(piece_arrays[marker_color],marker):
        if pt==(0,0): ar.append((name,a,mkbits(a,0,0)))
    output=[]
    for an,aa,am in ar:
        colors=[c for c in piece_arrays if c!=marker_color]
        ps_by_color={}
        bycell={c:[[] for _ in range(boardN*boardN)] for c in colors}
        for col in colors:
            ps=[]
            for name,a,_ in ori_records(piece_arrays[col]):
                h,w=a.shape
                for r in range(boardN-h+1):
                    for cc in range(boardN-w+1):
                        bm=mkbits(a,r,cc)
                        if bm&am: continue
                        p=(col,name,r,cc,bm)
                        ps.append(p)
                        bits=bm
                        while bits:
                            bit=bits&-bits; idx=bit.bit_length()-1
                            bycell[col][idx].append(p); bits-=bit
            ps_by_color[col]=ps
        sols=[]; nodes=0; cache=set()
        def dfs(occ,used,chosen):
            nonlocal nodes
            nodes+=1
            if len(used)==len(piece_arrays):
                if occ==full: sols.append(tuple(chosen))
                return len(sols)>=maxsol
            # select min valid options cell, candidates by remaining colors
            rem=full^occ; bits=rem
            bestopts=None
            while bits:
                bit=bits&-bits; idx=bit.bit_length()-1; bits-=bit
                opts=[]
                for col in colors:
                    if col not in used:
                        for p in bycell[col][idx]:
                            if not (p[4]&occ): opts.append(p)
                if not opts: return False
                if bestopts is None or len(opts)<len(bestopts):
                    bestopts=opts
                    if len(opts)==1: break
            for p in bestopts:
                if dfs(occ|p[4],used|{p[0]},chosen+[p]): return True
            return False
        dfs(am,{marker_color},[(marker_color,an,0,0,am)])
        output.append((an, len(sols),nodes, sols))
    return output

